INSERT INTO `news` (`id`, `title`, `short_description`, `description`, `category`, `photo`, `created_at`, `updated_at`) VALUES
(2, 'Annual Health Fair a Success', 'Over 500 residents benefit from free health screenings', 'The annual health fair attracted over 500 residents who received free health screenings and medical consultations.', 'Health', NULL, '2025-12-05 07:30:00', '2025-12-17 19:47:30'),
(3, 'Local School Wins National Science Competition', 'Local students win first place in national science competition', 'Students from Lideta High School won first place in the national science fair with their innovative renewable energy project.', 'Education', '{"url":"/uploads/science-fair.jpg","name":"science-fair.jpg"}', '2025-12-01 11:15:00', '2025-12-17 19:47:30'),
(4, 'Road Construction Project Begins', 'Infrastructure improvements begin in western part of the city', 'The much-anticipated road construction project in the western part of the sub-city has begun, expected to improve traffic flow.', 'Infrastructure', '[{"url":"/uploads/road-construction.jpg","name":"road-construction.jpg"}]', '2025-11-28 05:45:00', '2025-12-17 19:47:30'),
(5, 'New Waste Management Initiative Launched', 'New recycling program promotes environmental sustainability', 'A new recycling program has been launched to promote environmental sustainability in our community.', 'Environment', '[{"url":"/uploads/recycling.jpg","name":"recycling.jpg"}]', '2025-11-25 08:20:00', '2025-12-17 19:47:30'),
(6, 'Lideta Launches New Digital Service Center', 'New digital service center improves citizen access to municipal services', 'The Lideta Sub-City administration has launched a new digital service center designed to streamline services such as ID processing, tax inquiries, and community applications.', 'Technology', '[{"url":"/uploads/digital-center.jpg","name":"digital-center.jpg"}]', '2025-11-22 06:00:00', '2025-12-17 19:47:30'),
(7, 'Sub-City Undertakes Major Road Maintenance', 'Road maintenance project begins across multiple neighborhoods', 'A large-scale road maintenance initiative has begun to repair potholes and improve safety across several districts in the sub-city.', 'Infrastructure', '[{"url":"/uploads/road-maintenance.jpg","name":"road-maintenance.jpg"}]', '2025-11-18 04:30:00', '2025-12-17 19:47:30'),
(8, 'Local Library Expands Youth Programs', 'Youth programs expanded with new reading and computer classes', 'The Lideta public library has expanded its youth programs with new reading clubs, computer literacy classes, and weekend workshops.', 'Education', '[{"url":"/uploads/library-youth.jpg","name":"library-youth.jpg"}]', '2025-11-14 10:10:00', '2025-12-17 19:47:30'),
(9, 'Community Garden Initiative Grows', 'Residents volunteer to expand the community garden spaces', 'The community garden project continues to grow as local residents volunteer to plant vegetables, herbs, and flowers in shared public spaces.', 'Environment', '[{"url":"/uploads/community-garden.jpg","name":"community-garden.jpg"}]', '2025-11-10 07:40:00', '2025-12-17 19:47:30'),
(10, 'Lideta Hosts Annual Business Forum', 'Local business leaders gather to discuss growth strategies', 'The annual business forum brought together entrepreneurs and officials to discuss investment opportunities and strategies for local economic growth.', 'Business', '[{"url":"/uploads/business-forum.jpg","name":"business-forum.jpg"}]', '2025-11-07 05:55:00', '2025-12-17 19:47:30'),
(11, 'Public Park Renovation Completed', 'Major renovation of central park completed', 'Renovation of the central public park has been completed, featuring new playgrounds, walking paths, and improved lighting.', 'Community', '[{"url":"/uploads/park-renovation.jpg","name":"park-renovation.jpg"}]', '2025-11-03 12:20:00', '2025-12-17 19:47:30'),
(13, 'Youth Sports League Kicks Off', 'New youth sports season begins with football and athletics competitions', 'The youth sports league has officially begun, encouraging participation in football, athletics, and other activities to promote healthy living.', 'Sports', '[{"url":"/uploads/youth-sports.jpg","name":"youth-sports.jpg"}]', '2025-10-25 08:15:00', '2025-12-17 19:47:30'),
(28, 'Lideta Sub-City Launches Major Road Infrastructure Upgrade', 'Lideta Sub-City Administration has officially launched a comprehensive road rehabilitation project covering 12 key corridors across the sub-city.', 'Lideta Sub-City Administration has officially launched a comprehensive road rehabilitation project covering 12 key corridors across the sub-city. The project, funded through a joint initiative between the Addis Ababa City Administration and local government budget, aims to address long-standing transportation challenges and improve daily commutes for over 300,000 residents.\n\nThe rehabilitation program includes road widening, installation of modern drainage systems, pedestrian walkways, and street lighting upgrades. Construction crews have already begun work on the first phase, targeting the busiest arterial roads that connect residential neighborhoods to commercial zones.\n\nSub-City Administrator emphasized that this project is a milestone in the administration''s five-year development plan. "We are committed to delivering world-class infrastructure that reflects the aspirations of our residents," she stated during the project launch ceremony.\n\nThe entire project is expected to be completed within 18 months, with phase one set for delivery in the next six months. Residents are encouraged to follow traffic management advisories during the construction period.', 'Infrastructure', '{"name":"infrastructure.jpg","path":"https://images.unsplash.com/photo-1594708767771-a5a7c6e02acb?w=1200&q=80"}', '2026-08-23 07:05:13', '2026-08-23 07:05:13'),
(29, 'Free Health Screening Campaign Reaches 15,000 Residents', 'The Lideta Sub-City Health Office completed a three-week free health screening campaign providing services to over 15,000 residents across 8 health centers.', 'The Lideta Sub-City Health Office has successfully completed a three-week free health screening campaign, providing essential health services to over 15,000 residents across 8 community health centers throughout the sub-city.\n\nThe campaign, held in partnership with Addis Ababa Health Bureau and several NGO partners, offered screenings for diabetes, hypertension, tuberculosis, and maternal health. Mobile units were deployed to underserved neighborhoods to ensure no resident was left without access to care.\n\nHealth Office Director reported that over 2,300 residents were referred for follow-up treatment, and 450 previously undiagnosed cases of hypertension were identified. "Early detection saves lives," the director said. "This campaign is part of our commitment to preventive healthcare."\n\nThe sub-city administration has announced that similar campaigns will be held quarterly. Residents who could not attend are encouraged to visit their nearest health center for free consultations during the next campaign period.', 'Health', '{"name":"health.jpg","path":"https://images.unsplash.com/photo-1532938911079-1b06ac7ceec7?w=1200&q=80"}', '2026-08-23 07:05:14', '2026-08-23 07:05:14'),
(30, 'New Primary Schools Open in Three Neighborhoods', 'Three new fully equipped primary schools have been inaugurated across Lideta Sub-City, adding 2,400 new student seats to ease classroom overcrowding.', 'Three brand-new, fully equipped primary schools have been officially inaugurated across Lideta Sub-City, adding 2,400 new student seats and significantly easing the chronic classroom overcrowding that has affected educational quality for years.\n\nEach school features modern classrooms, a computer laboratory, a library, sanitation facilities, and a dedicated sports ground. The construction was financed through the city''s education fund supplemented by community contributions and private sector partnerships.\n\nThe Addis Ababa Education Bureau commended Lideta Sub-City Administration for prioritizing education. The bureau noted that the student-to-classroom ratio in the sub-city has improved from 65:1 to 45:1 following the new openings.\n\nParents and community leaders attended the inauguration ceremony and praised the administration for delivering the schools on schedule. Student enrollment for the next academic year is now open, with priority given to students from the surrounding neighborhoods.', 'Education', '{"name":"education.jpg","path":"https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=1200&q=80"}', '2026-08-23 07:05:15', '2026-08-23 07:05:15'),
(31, 'Lideta Sub-City Hosts Inter-Kebele Community Dialogue Forum', 'Over 500 community leaders, youth representatives, and residents gathered for a two-day inter-kebele dialogue forum focused on urban development priorities.', 'More than 500 community leaders, youth representatives, women''s groups, and residents from across Lideta Sub-City gathered for a two-day inter-kebele community dialogue forum, focusing on urban development priorities and public service improvement.\n\nThe forum, organized by the Sub-City Administration''s Community Affairs Office, featured panel discussions, working groups, and open floor sessions. Participants raised issues including waste management, traffic congestion, public park maintenance, and access to municipal services.\n\nAmong the key outcomes of the forum was an agreement to establish a permanent Community Advisory Council that will meet quarterly to provide feedback to the administration. The council will include representatives from all 10 kebeles within the sub-city.\n\n"Governance is most effective when it is participatory," said the Sub-City Administrator. "This forum demonstrates that when we listen to our residents, we can build a more responsive administration." A formal report of the forum''s recommendations will be published within 30 days.', 'Events', '{"name":"meeting.jpg","path":"https://images.unsplash.com/photo-1517048676732-d65bc937f952?w=1200&q=80"}', '2026-08-23 07:05:15', '2026-08-23 07:05:15'),
(32, 'Green Lideta: 50,000 Trees Planted in Sub-City Beautification Drive', 'Lideta Sub-City launched its landmark "Green Lideta" initiative, mobilizing residents and volunteers to plant 50,000 trees across parks, streets, and schools.', 'Lideta Sub-City Administration launched its landmark "Green Lideta" environmental initiative, mobilizing over 3,000 residents, school students, and volunteers to plant 50,000 trees across parks, street medians, school compounds, and open green spaces throughout the sub-city in a single weekend.\n\nThe initiative is part of Addis Ababa''s citywide green infrastructure program and aims to combat urban heat islands, improve air quality, and create more pleasant public spaces. Species selected include indigenous trees such as Warka (Ficus thonningii), Tidh (Juniperus procera), and various fruit-bearing trees that also benefit communities.\n\nThe Environment Office announced that follow-up maintenance teams will be assigned to each planting site for the next two years to ensure survival rates above 80%. A digital map of all planted sites will be made publicly available so residents can monitor progress.\n\n"Every tree we plant today is a gift to future generations," said the Sub-City Environment Officer. Community members who participated received certificates of recognition from the sub-city administration.', 'Environment', '{"name":"environment.jpg","path":"https://images.unsplash.com/photo-1504711434969-e33886168f5c?w=1200&q=80"}', '2026-08-23 07:05:16', '2026-08-23 07:05:16'),
(33, 'Lideta Sub-City Digital Services Portal Goes Live', 'Residents can now access over 30 municipal services online through the newly launched Lideta Digital Services Portal, reducing wait times and improving transparency.', 'Lideta Sub-City Administration has officially launched its Digital Services Portal, allowing residents to access more than 30 municipal services online without the need to visit government offices in person. The portal went live following a successful six-month pilot program.\n\nServices available through the portal include trade license renewal, birth and marriage certificate applications, property registration, utility complaint submission, and tracking of complaint resolution status. The system is accessible via both desktop and mobile devices and is available in Amharic, Oromo, and English.\n\nThe portal is part of a broader e-governance strategy that Addis Ababa City Administration has been rolling out across all sub-cities. User registration requires a valid national ID and a mobile phone number for verification.\n\n"This is a significant step toward making government services more accessible and reducing bureaucratic friction," said the Head of the ICT Department. Over 1,200 residents have already registered in the first week since launch, with trade license renewal being the most popular service.', 'Technology', '{"name":"community.jpg","path":"https://images.unsplash.com/photo-1591115765373-5207764f72e7?w=1200&q=80"}', '2026-08-23 07:05:17', '2026-08-23 07:05:17'),
(34, 'Sub-City Administration Cracks Down on Illegal Construction', 'Lideta Sub-City has demolished 47 illegally constructed structures and issued formal warnings to 120 property owners in a sweeping enforcement campaign.', 'In a decisive enforcement action, Lideta Sub-City Administration has demolished 47 illegally constructed structures and issued formal warnings to 120 additional property owners over a six-week period, as part of an intensified campaign to enforce urban planning regulations.\n\nThe structures included encroachments on public roads and pedestrian paths, unauthorized commercial buildings in residential zones, and constructions without valid permits. The campaign was coordinated between the Sub-City Urban Planning Office, the Addis Ababa City Administration, and local police.\n\nThe Urban Planning Office noted that illegal construction has been one of the primary obstacles to implementing the sub-city''s master plan. Property owners who demolish illegal structures voluntarily within the given notice period will not face additional penalties.\n\nResidents are reminded to obtain valid construction permits before beginning any building work. The Sub-City Urban Planning Office offers free consultations on permit requirements every Monday and Wednesday from 8:30 AM to 12:30 PM.', 'Security', '{"name":"road.jpg","path":"https://images.unsplash.com/photo-1566438480900-0609be27a4be?w=1200&q=80"}', '2026-08-23 07:05:18', '2026-08-23 07:05:18'),
(35, 'Youth Skills Training Center Enrolls 800 Young People', 'The Lideta Sub-City Youth and Sports Office has enrolled 800 young people in its latest round of vocational skills training programs covering IT, tailoring, and construction trades.', 'The Lideta Sub-City Youth and Sports Office has successfully enrolled 800 young people, aged 18 to 35, in its latest round of vocational skills training programs. The training, which covers information technology, tailoring and fashion design, carpentry, masonry, and electrical installation, is designed to equip young people with marketable skills and reduce youth unemployment.\n\nThe program is delivered in partnership with TVET institutions and private sector employers who have committed to offering employment opportunities to graduates. Training runs for three to six months depending on the track, with certification provided by the Ethiopian TVET Agency upon completion.\n\nPrevious rounds of the program have resulted in employment rates above 70% for graduates within six months of certification. The Youth Office noted that demand for the program has increased by 35% compared to the previous year, indicating strong community interest.\n\nYoung people interested in the next enrollment round are encouraged to register at the Sub-City Youth and Sports Office. Enrollment priority is given to young women, individuals with disabilities, and those from low-income households.', 'Education', '{"name":"school.jpg","path":"https://images.unsplash.com/photo-1503676260728-1c00da094a0b?w=1200&q=80"}', '2026-08-23 07:05:18', '2026-08-23 07:05:18'),
(36, 'Renovated Lideta Central Market Opens to Merchants and Public', 'After 14 months of construction, the fully renovated Lideta Central Market has re-opened, featuring modern stalls, improved sanitation, and fire safety systems.', 'After 14 months of intensive construction, the fully renovated Lideta Central Market has officially re-opened its doors to merchants and the public. The renovation project transformed the market from a congested, deteriorating facility into a modern, organized commercial hub with capacity for over 800 permanent stalls.\n\nKey improvements include dedicated zones for fresh produce, clothing, electronics, and food service; a centralized waste management system; modern sanitation blocks; integrated fire suppression systems; and CCTV surveillance for improved security.\n\nMerchants who were temporarily relocated during the construction period have been assigned new permanent stalls on a priority basis. The Sub-City Trade and Industry Office noted that rental rates for stalls have been maintained at pre-renovation levels to ease the transition.\n\n"This market is the economic heart of our sub-city," said the Sub-City Administrator at the inauguration ceremony. "Investing in it is investing in the livelihoods of thousands of families." The market is expected to generate 200 new permanent jobs through expanded service facilities.', 'Infrastructure', '{"name":"clinic.jpg","path":"https://images.unsplash.com/photo-1576091160399-112ba8d25d1d?w=1200&q=80"}', '2026-08-23 07:05:19', '2026-08-23 07:05:19'),
(37, 'Lideta Sub-City Recognized for Excellence in Public Service Delivery', 'Lideta Sub-City Administration received the Addis Ababa City Administration''s Award for Excellence in Public Service Delivery for the second consecutive year.', 'Lideta Sub-City Administration has received the Addis Ababa City Administration''s prestigious Award for Excellence in Public Service Delivery for the second consecutive year, recognizing outstanding performance across service delivery quality, citizen satisfaction, and administrative transparency.\n\nThe award, presented at the annual Addis Ababa Good Governance Conference, cited Lideta''s achievements in reducing average service wait times by 42%, achieving a citizen satisfaction score of 87% in the annual survey, and implementing a fully functional digital complaint management system.\n\nThe Sub-City Administrator accepted the award on behalf of the administration''s 1,200 staff members. "This recognition belongs to every employee who shows up every day committed to serving our residents, and to every resident who holds us accountable," she said.\n\nThe administration has committed to maintaining high service standards and announced plans to introduce three new digital services in the coming quarter, including an online property tax payment portal and a live tracking system for infrastructure maintenance requests.', 'Events', '{"name":"urban.jpg","path":"https://images.unsplash.com/photo-1464938050520-ef2270bb8ce8?w=1200&q=80"}', '2026-08-23 07:05:20', '2026-08-23 07:05:20'),
(38, 'Lideta Sub-City Launches Major Road Infrastructure Upgrade', 'Lideta Sub-City Administration has officially launched a comprehensive road rehabilitation project covering 12 key corridors across the sub-city.', 'Lideta Sub-City Administration has officially launched a comprehensive road rehabilitation project covering 12 key corridors across the sub-city. The project, funded through a joint initiative between the Addis Ababa City Administration and local government budget, aims to address long-standing transportation challenges and improve daily commutes for over 300,000 residents.\n\nThe rehabilitation program includes road widening, installation of modern drainage systems, pedestrian walkways, and street lighting upgrades. Construction crews have already begun work on the first phase, targeting the busiest arterial roads that connect residential neighborhoods to commercial zones.\n\nSub-City Administrator emphasized that this project is a milestone in the administration''s five-year development plan. "We are committed to delivering world-class infrastructure that reflects the aspirations of our residents," she stated during the project launch ceremony.\n\nThe entire project is expected to be completed within 18 months, with phase one set for delivery in the next six months. Residents are encouraged to follow traffic management advisories during the construction period.', 'Infrastructure', '{"name":"infrastructure.jpg","path":"https://images.unsplash.com/photo-1594708767771-a5a7c6e02acb?w=1200&q=80"}', '2026-08-23 07:05:38', '2026-08-23 07:05:38'),
(39, 'Free Health Screening Campaign Reaches 15,000 Residents', 'The Lideta Sub-City Health Office completed a three-week free health screening campaign providing services to over 15,000 residents across 8 health centers.', 'The Lideta Sub-City Health Office has successfully completed a three-week free health screening campaign, providing essential health services to over 15,000 residents across 8 community health centers throughout the sub-city.\n\nThe campaign, held in partnership with Addis Ababa Health Bureau and several NGO partners, offered screenings for diabetes, hypertension, tuberculosis, and maternal health. Mobile units were deployed to underserved neighborhoods to ensure no resident was left without access to care.\n\nHealth Office Director reported that over 2,300 residents were referred for follow-up treatment, and 450 previously undiagnosed cases of hypertension were identified. "Early detection saves lives," the director said. "This campaign is part of our commitment to preventive healthcare."\n\nThe sub-city administration has announced that similar campaigns will be held quarterly. Residents who could not attend are encouraged to visit their nearest health center for free consultations during the next campaign period.', 'Health', '{"name":"health.jpg","path":"https://images.unsplash.com/photo-1532938911079-1b06ac7ceec7?w=1200&q=80"}', '2026-08-23 07:05:39', '2026-08-23 07:05:39'),
(40, 'New Primary Schools Open in Three Neighborhoods', 'Three new fully equipped primary schools have been inaugurated across Lideta Sub-City, adding 2,400 new student seats to ease classroom overcrowding.', 'Three brand-new, fully equipped primary schools have been officially inaugurated across Lideta Sub-City, adding 2,400 new student seats and significantly easing the chronic classroom overcrowding that has affected educational quality for years.\n\nEach school features modern classrooms, a computer laboratory, a library, sanitation facilities, and a dedicated sports ground. The construction was financed through the city''s education fund supplemented by community contributions and private sector partnerships.\n\nThe Addis Ababa Education Bureau commended Lideta Sub-City Administration for prioritizing education. The bureau noted that the student-to-classroom ratio in the sub-city has improved from 65:1 to 45:1 following the new openings.\n\nParents and community leaders attended the inauguration ceremony and praised the administration for delivering the schools on schedule. Student enrollment for the next academic year is now open, with priority given to students from the surrounding neighborhoods.', 'Education', '{"name":"education.jpg","path":"https://images.unsplash.com/photo-1497633762265-9d179a990aa6?w=1200&q=80"}', '2026-08-23 07:05:39', '2026-08-23 07:05:39'),
(41, 'Lideta Sub-City Hosts Inter-Kebele Community Dialogue Forum', 'Over 500 community leaders, youth representatives, and residents gathered for a two-day inter-kebele dialogue forum focused on urban development priorities.', 'More than 500 community leaders, youth representatives, women''s groups, and residents from across Lideta Sub-City gathered for a two-day inter-kebele community dialogue forum, focusing on urban development priorities and public service improvement.\n\nThe forum, organized by the Sub-City Administration''s Community Affairs Office, featured panel discussions, working groups, and open floor sessions. Participants raised issues including waste management, traffic congestion, public park maintenance, and access to municipal services.\n\nAmong the key outcomes of the forum was an agreement to establish a permanent Community Advisory Council that will meet quarterly to provide feedback to the administration. The council will include representatives from all 10 kebeles within the sub-city.\n\n"Governance is most effective when it is participatory," said the Sub-City Administrator. "This forum demonstrates that when we listen to our residents, we can build a more responsive administration." A formal report of the forum''s recommendations will be published within 30 days.', 'Events', '{"name":"meeting.jpg","path":"https://images.unsplash.com/photo-1517048676732-d65bc937f952?w=1200&q=80"}', '2026-08-23 07:05:40', '2026-08-23 07:05:40');
